import {readFile,writeFile} from 'node:fs/promises';import {createHash} from 'node:crypto';import assert from 'node:assert/strict';import ts from 'typescript';
const root='.local/step07-review/independent-round11',src=await readFile('apps/api/tests/studio/stored-zip.ts','utf8');await writeFile(root+'/private/stored-exact.mjs',ts.transpileModule(src,{compilerOptions:{module:ts.ModuleKind.ESNext,target:ts.ScriptTarget.ES2022}}).outputText);const {readStoredStandardZip}=await import('./stored-exact.mjs');const normal=JSON.parse(await readFile(root+'/evidence/latest-browser-archive-verification.json','utf8')).downloads,negative=JSON.parse(await readFile(root+'/evidence/latest-archive-negative-verification.json','utf8'));const rows=[];
for(const x of [...normal.map(x=>({...x,expectedAccepted:true})),...negative]){const b=await readFile(root+'/'+x.file);let accepted,error;try{const files=readStoredStandardZip(b);assert.equal(Object.keys(files).length,8);accepted=true}catch(e){error=e.message;accepted=false}assert.equal(accepted,x.expectedAccepted);rows.push({file:x.file,expectedAccepted:x.expectedAccepted,candidateAccepted:accepted,error,sha256:createHash('sha256').update(b).digest('hex')})}
await writeFile(root+'/evidence/current-candidate-reader-controls.json',JSON.stringify({source:'dc61fe03f64e644b7ac63057b3f7d7d26df547f8',candidateHelperSHA256:createHash('sha256').update(src).digest('hex'),scope:'actual current downloads and local consumer negatives; not four new wire fault positions',rows},null,2)+'\n');console.log(JSON.stringify({normalAccepted:normal.length,negativeRejected:negative.length}));
